-- =============================================================================
-- PatoVetZee — migração 002: banco de doenças no Supabase + painel de admin
-- -----------------------------------------------------------------------------
-- Como usar: abra o SQL Editor do seu projeto Supabase e rode este arquivo
-- INTEIRO de uma vez (schema + as ~188 doenças migradas do jogo atual).
-- Depois disso, veja o final deste arquivo — falta 1 passo manual (te tornar
-- admin) que só você pode fazer.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. PERFIS — adiciona a flag de administrador
-- -----------------------------------------------------------------------------
alter table public.perfis
  add column if not exists is_admin boolean not null default false;

-- -----------------------------------------------------------------------------
-- 2. DOENÇAS — o banco inteiro, agora editável pelo painel de admin do jogo
-- -----------------------------------------------------------------------------
create table public.doencas (
  id text primary key,                        -- mesmo id usado no jogo (ex.: "raiva_canina")
  nome text not null,
  especie text not null,
  sistema text not null,                       -- uma das chaves de CATALOGO_SISTEMAS
  dica text,                                   -- reservado (não usado hoje)
  parametros_binarios jsonb not null default '{}'::jsonb,
  parametros_graduais jsonb not null default '{}'::jsonb,
  criado_em timestamptz not null default now(),
  atualizado_em timestamptz not null default now()
);

create index doencas_sistema_idx on public.doencas (sistema);
create index doencas_especie_idx on public.doencas (especie);

-- Mantém `atualizado_em` sempre correto em qualquer update, sem precisar que
-- o app lembre de mandar o campo.
create or replace function public.tocar_atualizado_em()
returns trigger
language plpgsql
as $$
begin
  new.atualizado_em = now();
  return new;
end;
$$;

create trigger doencas_atualiza_timestamp
  before update on public.doencas
  for each row
  execute function public.tocar_atualizado_em();

alter table public.doencas enable row level security;

-- Qualquer pessoa (logada ou não) pode LER o banco inteiro — é o conteúdo do
-- jogo, não é dado sensível. É o que permite o app carregar as doenças mesmo
-- pra quem não fez login.
create policy "doencas_leitura_publica"
  on public.doencas for select
  using (true);

-- Só quem tem is_admin=true no próprio perfil pode criar/editar/apagar.
create policy "doencas_admin_insere"
  on public.doencas for insert
  with check (exists (select 1 from public.perfis where id = auth.uid() and is_admin = true));

create policy "doencas_admin_atualiza"
  on public.doencas for update
  using (exists (select 1 from public.perfis where id = auth.uid() and is_admin = true))
  with check (exists (select 1 from public.perfis where id = auth.uid() and is_admin = true));

create policy "doencas_admin_apaga"
  on public.doencas for delete
  using (exists (select 1 from public.perfis where id = auth.uid() and is_admin = true));

grant select on public.doencas to anon, authenticated;
grant insert, update, delete on public.doencas to authenticated;

-- -----------------------------------------------------------------------------
-- 3. Dados: as doenças já cadastradas no jogo hoje, migradas de uma vez.
--    "on conflict do nothing" torna seguro rodar este arquivo mais de uma vez
--    por engano — não sobrescreve nada que já esteja na tabela.
-- -----------------------------------------------------------------------------
on conflict (id) do nothing;

-- -----------------------------------------------------------------------------
-- 4. PASSO MANUAL — só você pode fazer isso (eu não tenho acesso de escrita
--    ao seu banco, só a anon key que já está no jogo).
-- -----------------------------------------------------------------------------
-- Depois de rodar tudo acima, torne sua própria conta admin. Troque
-- 'seu_apelido_aqui' pelo apelido que você usa no jogo (o mesmo da tela de
-- login) e rode só esta linha:

-- update public.perfis set is_admin = true where apelido = 'seu_apelido_aqui';

-- Se preferir localizar por e-mail em vez de apelido, use:
-- update public.perfis set is_admin = true
--   where id = (select id from auth.users where email = 'seu@email.com');

-- Depois disso, faça login normalmente no jogo — a aba "Administração"
-- aparece automaticamente na tela inicial pra quem tem is_admin = true.
